{
  "finding": "recoverArtifact 仅能恢复 body.status==='complete' 的不可变产物。runReservedSeat 在 writeFileSync 完成后、saveLedger 前崩溃时，会留下 body.status==='incomplete_or_failed' 的已落盘 artifact，但 ledger 仍为 generation_started 且 seat.artifact 为空。recoverArtifact 扫描到该失败候选后 validateArtifact 固定抛 artifact_binding_invalid，matches.length===0，返回 false；syncDailyBoard 继而把席位永久写成 generation_unknown_no_repurchase，该状态不会再进入 artifact 提交或 syncFailedSeat 路径，导致失败证据断链且无法闭环。",
  "evidence_paths": [
    "scripts/lib/daily-task-board.mjs"
  ],
  "minimal_patch": "在 recoverArtifact 中新增失败候选恢复分支：

function validateFailedArtifact(root, record, agent, seat, hash) {
  const path = `knowledge/results/daily-board/artifacts/${record.date}-${agent}-${hash}.json`;
  const bytes = fs.readFileSync(path.join(root, path));
  if (digest(bytes) !== hash) throw Error('artifact_hash_mismatch');
  const body = JSON.parse(bytes);
  if (body.status !== 'incomplete_or_failed' || body.date !== record.date || body.run_key !== record.run_key || body.task_id !== seat.assignment?.id || body.logical_seat !== agent || body.source_commit !== record.source_commit) throw Error('artifact_binding_invalid');
  return { path, sha256: hash };
}

export function recoverArtifact(root, record, agent, seat) {
  if (!['generation_started','generation_unknown_no_repurchase'].includes(seat.status) || seat.artifact || !seat.assignment || !seat.claim_verified) return false;
  const directory = path.join(root,'knowledge/results/daily-board/artifacts');
  if (!fs.existsSync(directory)) return false;
  const prefix = `${record.date}-${agent}-`;
  const completeMatches = [];
  const failedMatches = [];
  for (const name of fs.readdirSync(directory).filter(n=>n.startsWith(prefix) && n.endsWith('.json'))) {
    const hash = name.slice(prefix.length,-5);
    const candidate = {...seat, artifact:{path:`knowledge/results/daily-board/artifacts/${name}`,sha256:hash}};
    try { validateArtifact(root,record,agent,candidate); completeMatches.push(candidate.artifact); } catch {}
    try { failedMatches.push(validateFailedArtifact(root, record, agent, seat, hash)); } catch {}
  }
  if (failedMatches.length === 1) {
    seat.artifact = failedMatches[0];
    seat.status = 'generation_failed_no_repurchase';
    seat.recovery = 'immutable_failed_artifact_verified_no_model_replay';
    saveLedger(root,record);
    return true;
  }
  if (completeMatches.length !== 1) return false;
  seat.artifact = completeMatches[0];
  seat.status = 'generated_pending_sync';
  seat.recovery = 'immutable_artifact_verified_no_model_replay';
  saveLedger(root,record);
  return true;
}",
  "verification_commands": [
